import openpyxl

wb = openpyxl.load_workbook('/Users/tranhaibang/Downloads/Bao_Cao_Tai_Chinh_Quan_Tri_120Ty.xlsx', data_only=False)

def check_sheet_formulas(ws):
    print(f'Checking {ws.title}...')
    for r in range(1, ws.max_row+1):
        for c in range(1, ws.max_column+1):
            val = ws.cell(r, c).value
            if val and str(val).startswith('='):
                # Basic syntax check
                formula = str(val)[1:]
                # Check balanced parens
                if formula.count('(') != formula.count(')'):
                    print(f'ERROR: Unbalanced parens in {ws.title}!{ws.cell(r, c).coordinate}: {val}')
                # Check for empty references or strange chars
                if '#REF' in formula:
                    print(f'ERROR: #REF in {ws.title}!{ws.cell(r, c).coordinate}: {val}')

for sheetname in wb.sheetnames:
    check_sheet_formulas(wb[sheetname])

print('All formula syntax checks passed!')
